import{_ as a,o as d,c as o,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const P=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/LOOP.md","filePath":"manual-zh/LOOP.md","lastUpdated":1785684581000}'),t={name:"manual-zh/LOOP.md"};function r(c,e,O,p,i,s){return d(),o("div",null,[...e[0]||(e[0]=[n(`<h3 id="_14-5-loop" tabindex="-1">14.5 LOOP <a class="header-anchor" href="#_14-5-loop" aria-label="Permalink to &quot;14.5 LOOP&quot;">​</a></h3><pre><code>LOOP [index_var=start TO end [BY incr]] [IF condition].
        …
END LOOP [IF condition].
</code></pre><p><code>LOOP</code> 对一组命令进行迭代。它提供了多种终止选项。</p><p>指定 index_var 可使该变量按特定增量从一个值计数到另一个值。index_var 必须是已存在的数值变量。start、end 和 incr 是数值表达式（参见 <a href="./Expressions">Expressions</a>。）。</p><p>在第一次迭代时，index_var 被设为 start 的值。在随后的每次迭代中，index_var 按 incr 的值递增。如果 end &gt; start，则当 index_var &gt; end 时循环终止；否则当 index_var &lt; end 时循环终止。如果未指定 incr，则默认为适当的 +1 或 -1。</p><p>如果 end &gt; start 且 incr &lt; 0，或者 end &lt; start 且 incr &gt; 0，则循环从不执行。尽管如此，index_var 仍会被设为 start 的值。</p><p>允许在循环内修改 index_var，但这对下一次迭代中 index_var 的值没有影响。</p><p>在 <code>LOOP</code> 上指定一个布尔表达式作为条件，可使循环仅在该条件为真时执行。如果在第一次执行循环内容之前条件为假或缺失，则循环内容根本不会执行。</p><p>如果 index 子句和条件子句同时出现在 <code>LOOP</code> 上，则索引变量总是在条件求值之前被设置。因此，使用索引变量的条件总是会看到下一次执行循环体时要使用的索引值。</p><p>在 <code>END LOOP</code> 上指定一个布尔表达式作为条件，可使所包含的代码块执行后，若条件为真则循环终止。该条件在循环末尾而非开头求值，因此仅带有 <code>END LOOP</code> 条件的循环体总是至少执行一次。</p><p>如果未出现 index 子句，则全局 <code>MXLOOPS</code> 设置（默认为 40）限制迭代次数（参见 <a href="./SET#SET-MXLOOPS">SET MXLOOPS</a>）。</p><p><code>BREAK</code> 也会终止 <code>LOOP</code> 的执行（参见 <a href="./BREAK">BREAK</a>）。</p><p>循环索引变量默认在个案之间被重置为系统缺失值，而非保留，除非使用暂存变量作为索引。当循环嵌套时，这通常是不期望的行为，可通过 <code>LEAVE</code>（参见 <a href="./LEAVE">LEAVE</a>）或使用暂存变量作为循环索引来纠正。</p><p>当 <code>LOOP</code> 或 <code>END LOOP</code> 在 <code>TEMPORARY</code> 之后指定时（参见 <a href="./TEMPORARY">TEMPORARY</a>），不能使用 <code>LAG</code> 函数（参见 <a href="./Miscellaneous-Functions#LAG">LAG</a>）。</p>`,14)])])}const L=a(t,[["render",r]]);export{P as __pageData,L as default};
